description:
Implement a binary-to-BCD converter that takes an 8-bit binary input and produces a 12-bit BCD output. The module parses the binary value into three separate BCD digits, where `digit1` represents the hundreds place, `digit2` the tens place, and `digit3` the units place. It handles values from 0 to 255 by appropriately allocating zeros for leading digits when necessary, ensuring the resulting BCD format is ready for further processing or display.
module top_module(
    input [7:0] binary,
    output [11:0] bcd
);

code:
module top_module(
    input [7:0] binary,
    output [11:0] bcd
);reg [3:0] digit1;
reg [3:0] digit2;
reg [3:0] digit3;

always @ (binary) begin
    if (binary >= 100) begin
        digit1 = binary / 100;
        digit2 = (binary % 100) / 10;
        digit3 = binary % 10;
    end else if (binary >= 10) begin
        digit1 = 0;
        digit2 = binary / 10;
        digit3 = binary % 10;
    end else begin
        digit1 = 0;
        digit2 = 0;
        digit3 = binary;
    end
end

assign bcd = {digit1, digit2, digit3};

endmodule

