module debouncer(
    input               clk,
    input               rst,
    input               noisy_signal,

    output reg          clean_signal
);

reg [3:0] shift_reg;
always@(posedge clk or posedge rst) begin
    if (rst) 
        shift_reg <= 4'b0000;
    else 
        shift_reg <= {shift_reg[2:0], noisy_signal};
end

always@(posedge clk or posedge rst) begin
    if (rst)
        clean_signal <= 1'b0;
    else if (shift_reg == 4'b1111)
        clean_signal <= 1'b1;
    else if (shift_reg == 4'b0000)
        clean_signal <= 1'b0;
end

endmodule

