module top_module(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_a     ,
    input               ready_b     ,

    output              ready_a     ,
    output  reg         valid_b     ,
    output  reg [31:0]  data_out
);reg [7:0] data_reg [3:0];
reg [31:0] acc_reg [2:0];
reg [1:0] stage;

assign ready_a = (stage == 2) ? 1'b1 : 1'b0;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        // Initialize each register individually
        data_reg[0] <= 8'b0;
        data_reg[1] <= 8'b0;
        data_reg[2] <= 8'b0;
        data_reg[3] <= 8'b0;
        acc_reg[0] <= 32'b0;
        acc_reg[1] <= 32'b0;
        acc_reg[2] <= 32'b0;
        stage <= 0;
        valid_b <= 0;
        data_out <= 0;
    end else begin
        case (stage)
            0: begin
                if (valid_a) begin
                    data_reg[0] <= data_in;
                    stage <= 1;
                end
            end
            1: begin
                if (valid_a) begin
                    data_reg[1] <= data_reg[0];
                    data_reg[0] <= data_in;
                    stage <= 2;
                end
            end
            2: begin
                acc_reg[0] <= acc_reg[0] + {data_reg[1], data_reg[0]};
                stage <= 3;
            end
            3: begin
                acc_reg[1] <= acc_reg[1] + acc_reg[0];
                stage <= 4;
            end
            4: begin
                acc_reg[2] <= acc_reg[2] + acc_reg[1];
                stage <= 0;
                valid_b <= 1;
                data_out <= acc_reg[2];
            end
        endcase
    end
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        valid_b <= 0;
    end else begin
        if (valid_b && ready_b) begin
            valid_b <= 0;
        end
    end
end

endmodule

