Implement the Verilog module based on the following description.
Build a 5-bit up/down counter with synchronous active high reset signal and direction control.
// (1) reset: Resets the counter to 5'b00000.
// (2) up: Direction control signal. When high, count up. When low, count down.
// (3) q: The value of the counter.

module top_module(
    input clk,
    input reset,
    input up,
    output reg [4:0] q);

code:
module top_module(
    input clk,
    input reset,
    input up,
    output reg [4:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the counter to 5'b00000
            q <= 5'b00000;
        end else begin
            // Up/down counter: Increment or decrement based on the 'up' signal
            if (up) begin
                q <= q + 1;
            end else begin
                q <= q - 1;
            end
        end
    end

endmodule

