module top_module(
    input clk,
    input rst,
    input write_en,
    input [15:0] write_data,
    input read_en,
    output reg full,
    output reg empty,
    output reg [15:0] read_data
);reg [15:0] buffer [0:15];
reg [3:0] write_ptr;
reg [3:0] read_ptr;

always @(posedge clk or negedge rst) begin
    if(!rst) begin
        write_ptr <= 4'b0000;
        read_ptr <= 4'b0000;
        full <= 1'b0;
        empty <= 1'b1;
    end
    else begin
        if(write_en && !full) begin
            buffer[write_ptr] <= write_data;
            write_ptr <= write_ptr + 1;
            if(write_ptr == 4'b1111) begin
                write_ptr <= 4'b0000;
            end
            if(write_ptr == read_ptr) begin
                full <= 1'b1;
            end
            empty <= 1'b0;
        end
        if(read_en && !empty) begin
            read_data <= buffer[read_ptr];
            read_ptr <= read_ptr + 1;
            if(read_ptr == 4'b1111) begin
                read_ptr <= 4'b0000;
            end
            if(read_ptr == write_ptr) begin
                empty <= 1'b1;
            end
            full <= 1'b0;
        end
    end
end

endmodule

