module fsm (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter X=0, Y=1, Z=2;

    always_comb begin
        case (state)
            X: next_state = in ? Z : Y;
            Y: next_state = in ? X : Z;
            Z: next_state = in ? Y : X;
        endcase
    end

    assign out = (state==Y);

endmodule

