module sequence_detector (
    input clk,
    input reset,
    input seq_in,
    output reg seq_detected);parameter IDLE = 0, S1 = 1, S10 = 2, S101 = 3, S1011 = 4;
    reg [2:0] state, next;

    always @(posedge clk or posedge reset) begin
        if (reset) state <= IDLE;
        else state <= next;
    end

    always @(*) begin
        case (state)
            IDLE: next = seq_in ? S1 : IDLE;
            S1: next = seq_in ? S1 : S10;
            S10: next = seq_in ? S101 : IDLE;
            S101: next = seq_in ? S1 : S1011;
            S1011: next = seq_in ? S1 : IDLE;
            default: next = IDLE;
        endcase
    end

    always @(*) begin
        seq_detected = (state == S1011) ? 1 : 0;
    end

endmodule

