module top_module(clk, reset_n, pause_req, pause_val, tx_pause);input clk, reset_n, pause_req;
	input [15:0] pause_val;
	output wire tx_pause;

	reg [18:0] count;
	reg counting;

	assign tx_pause = counting;

	always@ (posedge clk or negedge reset_n) begin
		if(~reset_n) begin
			count <= 19'h0;
			counting <= 1'b0;
		end
		else
		begin
			if(count == 19'h0) begin
				counting <= 1'b0;
			end
			if(pause_req) begin
				counting <= 1'b1;
				count <= pause_val << 3;
			end
			if(counting) begin
				count <= count - 1;
			end
		end
	end

endmodule

