description:
Design a circuit that generates a one-second clock signal (clk_out) from a given high-frequency input clock. The module divides the input clock frequency by 50 million, toggling the output signal every time the counter reaches this value. It includes a reset input (rst) to initialize the output and counter, ensuring a reliable start-up condition.
module top_module(
clock , 
rst , 
clk_out 
);

code:
module top_module(
clock , 
rst , 
clk_out 
);input clock ;
input rst ;
output clk_out;



wire clock ;
wire rst ;



reg clk_out;
reg [31:0] clk_div ;



always @ (posedge clock)
begin


    if (rst === 1'b1) begin
        clk_out <= #1 1'b0;
        clk_div <= #1 32'd0;
    end
    else begin

    clk_div <= #1 clk_div + 1;
    end

    if (clk_div === 32'd50000000)
    begin
    clk_out <= #1 ~clk_out;
    clk_div <= #1 32'd0;
    end
end 
endmodule

module top_module(
    input clk,
    input reset, // Synchronous active-high reset
    output reg [3:0] counter_out, // 4-bit output from the counter
    input [3:0] encoder_in, // 4-bit input for the priority encoder
    output reg [1:0] encoder_out, // 2-bit output from the priority encoder
    output reg [3:0] and_out // 4-bit output from the AND module
);reg [3:0] counter_reg; // Register to hold the counter value

// Counter module
always @(posedge clk) begin
    if (reset) begin
        counter_reg <= 4'b0000;
    end else begin
        counter_reg <= counter_reg + 1;
    end
end

assign counter_out = counter_reg;

// Priority encoder module
always @* begin
    case(encoder_in)
        4'b0001: encoder_out = 2'b00;
        4'b0010: encoder_out = 2'b01;
        4'b0100: encoder_out = 2'b10;
        4'b1000: encoder_out = 2'b11;
        default: encoder_out = 2'b00;
    endcase
end

// AND module
always @* begin
    and_out = counter_reg & {2'b00, encoder_out};
end

endmodule

