module debouncer(
    input               clk,
    input               rst_n,
    input               switch_in,
    output reg          switch_out
);

reg [3:0] shift_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 4'b0000;
        switch_out <= 1'b0;
    end else begin
        shift_reg <= {shift_reg[2:0], switch_in};
        if (shift_reg == 4'b1111) begin
            switch_out <= 1'b1;
        end else if (shift_reg == 4'b0000) begin
            switch_out <= 1'b0;
        end
    end
end

endmodule

