module top_module(input clock, input reset, input[5:0] counter, output reg clock_out);reg[5:0] temp_counter; 
  initial 
  begin 
  temp_counter <= 6'b0; 
  clock_out <= 1'b0; 
  end 
  always @(posedge clock or posedge reset) 
  begin 
  if(reset) 
  begin 
  temp_counter <= 6'b0; 
  clock_out <= 1'b0; 
  end 
  else 
  if(temp_counter == counter) 
  begin 
  temp_counter <= 6'b0; 
  clock_out <= ~clock_out; 
  end 
  else 
  begin 
  temp_counter <= temp_counter + 1; 
  end 
  end 
 endmodule

module top_module(
  input clk,
  input reset,
  input count_en,
  output reg [3:0] count_val
);reg [3:0] next_val;

  always @(posedge clk) begin
    if (reset) begin
      count_val <= 4'b0000;
    end
    else if (count_en) begin
      case (count_val)
        4'b0000: next_val <= 4'b0001;
        4'b0001: next_val <= 4'b0010;
        4'b0010: next_val <= 4'b0011;
        4'b0011: next_val <= 4'b0100;
        4'b0100: next_val <= 4'b0101;
        4'b0101: next_val <= 4'b0110;
        4'b0110: next_val <= 4'b0111;
        4'b0111: next_val <= 4'b1000;
        4'b1000: next_val <= 4'b1001;
        4'b1001: next_val <= 4'b1010;
        4'b1010: next_val <= 4'b1011;
        4'b1011: next_val <= 4'b1100;
        4'b1100: next_val <= 4'b1101;
        4'b1101: next_val <= 4'b1110;
        4'b1110: next_val <= 4'b1111;
        4'b1111: next_val <= 4'b0000;
      endcase
      count_val <= next_val;
    end
  end

endmodule

