  input clk,        // Add clock input
  input in,        // Input data
  output reg [1:0] out1, // Output from encoder 1
  output reg [1:0] out2  // Output from encoder 2
);parameter k = 4; // constraint length of the convolutional codes
parameter n = 2; // number of parallel convolutional codes
parameter m = 8; // length of the interleaver

reg [k-1:0] shift_reg1; // shift register for convolutional encoder 1
reg [k-1:0] shift_reg2; // shift register for convolutional encoder 2
reg [m-1:0] interleave_table [0:m-1]; // interleaver table
integer i; // Declare loop variable

// Convolutional encoder 1
always @(posedge clk) begin
  shift_reg1 <= {in, shift_reg1[k-2:0]};
  case(shift_reg1)
    4'b0000: out1 <= 2'b00;
    4'b0001: out1 <= 2'b01;
    4'b0010: out1 <= 2'b11;
    4'b0011: out1 <= 2'b10;
    // Add other cases for all possible input combinations
    default: out1 <= 2'b00; // Default case
  endcase
end

// Convolutional encoder 2
always @(posedge clk) begin
  shift_reg2 <= {in, shift_reg2[k-2:0]};
  case(shift_reg2)
    4'b0000: out2 <= 2'b00;
    4'b0001: out2 <= 2'b10;
    4'b0010: out2 <= 2'b11;
    4'b0011: out2 <= 2'b01;
    // Add other cases for all possible input combinations
    default: out2 <= 2'b00; // Default case
  endcase
end

// Interleaver
always @(posedge clk) begin
  for (i = 0; i < m; i = i + 1) begin
    interleave_table[i] <= {in, interleave_table[i][m-1:1]}; // Correct indexing for interleaving
  end
end

