module top_module(
    input clk,
    input reset,
    input data_in,
    output reg data_out,
    output locked
);parameter DELAY_LENGTH = 10; // number of delay stages in the delay chain
parameter LOCK_THRESHOLD = 5; // number of cycles before locking

reg [DELAY_LENGTH-1:0] delay_chain; // delay chain
reg [4:0] lock_counter; // lock counter
reg locked_reg; // locked register

always @(posedge clk) begin
    if (reset) begin
        delay_chain <= 0;
        lock_counter <= 0;
        locked_reg <= 0;
        data_out <= 0;
    end else begin
        // shift the delay chain
        delay_chain <= {delay_chain[DELAY_LENGTH-2:0], data_in};

        // increment or reset lock counter
        if (delay_chain == {DELAY_LENGTH{1'b1}} || delay_chain == {DELAY_LENGTH{1'b0}}) begin
            lock_counter <= lock_counter + 1;
        end else begin
            lock_counter <= 0;
        end

        // set locked register
        if (lock_counter >= LOCK_THRESHOLD) begin
            locked_reg <= 1;
        end else begin
            locked_reg <= 0;
        end

        // output delayed data
        data_out <= delay_chain[DELAY_LENGTH-1];
    end
end

assign locked = locked_reg;

endmodule

